import { domainToASCII } from 'node:url';

/**
 * Expected values for WHOIS Lookup (/whois) and the shared snapshot view.
 *
 * The tool shows a snapshot the backend built (POST /api/whois). In contract
 * tests the snapshot is generated by ./generator.ts, so the snapshot is the
 * ground truth and this file states, in words and then in code, how each
 * field must appear. Nothing here imports application code.
 *
 * Definitions
 *  - Lookup target: what the user typed, reduced to a host name. The page says
 *    "Input accepts a bare domain or URL", so a URL is reduced with the WHATWG
 *    URL parser (scheme, credentials, port, path, query and fragment removed)
 *    and the host is compared case-insensitively in its ASCII (punycode) form.
 *  - Dates: every date is shown in UTC as `DD Mon YYYY HH:MM UTC` (the page
 *    labels them "UTC"). An empty date is "Unknown". A value that is not a
 *    date is shown as received.
 *  - Days until expiry: the number in the snapshot, which the backend defines
 *    as ceil((expiry - check time) / 1 day). No expiry date: "Unknown".
 *    Colour: grey when unknown, red when negative (expired), amber for 0..30
 *    (the backend raises "expires within 30 days" for the same range),
 *    green above 30.
 *  - DNSSEC: the snapshot word (signed / unsigned / unknown); green, amber, grey.
 *  - Source: "RDAP" when data_source is rdap, otherwise "WHOIS". The word is
 *    reused in four labels (nameserver list, "Only In ...", raw section, raw
 *    button) and in the empty-status sentence.
 *  - Missing values: registrar, IANA id, abuse e-mail and phone show
 *    "Unknown"; empty lists show "None"; nameserver_match null shows "Unknown".
 *  - Contacts: one card per role that has a name, e-mail or phone, in the
 *    order Registrant, Admin, Tech, each listing only the parts that exist.
 *    No contact at all: no Contacts section.
 *  - A snapshot with missing or mistyped fields is completed with neutral
 *    defaults (empty text, empty list, null, "unknown", source WHOIS,
 *    not registered) rather than crashing.
 */

export const TIME_ZONE = process.env.E2E_TIMEZONE ?? 'America/New_York';
export const DAY_MS = 86_400_000;

export interface Contact { name: string; email: string; phone: string }

export interface Snapshot {
  domain: string;
  query_domain: string;
  data_source: 'rdap' | 'whois';
  registered: boolean;
  status_labels: string[];
  status_codes: string[];
  registrar: string;
  registrar_iana_id: string;
  abuse_email: string;
  abuse_phone: string;
  creation_date: string;
  updated_date: string;
  expiry_date: string;
  days_until_expiry: number | null;
  nameservers: string[];
  dns_nameservers: string[];
  nameserver_match: boolean | null;
  nameserver_only_in_whois: string[];
  nameserver_only_in_dns: string[];
  dnssec: 'signed' | 'unsigned' | 'unknown';
  privacy_detected: boolean;
  privacy_provider: string;
  contacts: { registrant: Contact; admin: Contact; tech: Contact };
  risk_signals: string[];
  raw_response: string;
  raw_whois: string;
  rdap_metadata: { base_url: string; handle: string } | null;
  checked_at_utc: string;
}

// ─── Input ───────────────────────────────────────────────────────────────────

/** ASCII host name a typed value stands for; '' when it names no host. */
export function lookupTarget(typed: string): string {
  const text = typed.trim();
  if (!text) return '';
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(text) ? text : `http://${text}`;
  try {
    return new URL(withScheme).hostname.toLowerCase();
  } catch {
    return '';
  }
}

/** The domain a request carries, in the form `lookupTarget` returns. */
export function asciiHost(sent: unknown): string {
  return typeof sent === 'string' ? domainToASCII(sent.trim().toLowerCase()) : '';
}

// ─── Dates ───────────────────────────────────────────────────────────────────

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const two = (n: number) => String(n).padStart(2, '0');

export function utcStamp(value: string): string {
  if (!value) return 'Unknown';
  const ms = Date.parse(value);
  if (Number.isNaN(ms)) return value;
  const d = new Date(ms);
  return `${two(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()} ${two(d.getUTCHours())}:${two(d.getUTCMinutes())} UTC`;
}

/**
 * British English abbreviates September as "Sept" in recent Unicode locale
 * data and as "Sep" in older data. Both are correct; compare in one form.
 */
export function sameMonthSpelling(text: string): string {
  return text.replace(/\bSept\b/g, 'Sep');
}

/** `Nov 27, 2026` for the browser's zone: how the shared page dates a link. */
export function localDay(value: string | number | Date): string {
  return new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric', timeZone: TIME_ZONE }).format(new Date(value));
}

export function daysUntil(expiryIso: string, atIso: string): number | null {
  if (!expiryIso) return null;
  const expiry = Date.parse(expiryIso);
  if (Number.isNaN(expiry)) return null;
  const days = Math.ceil((expiry - Date.parse(atIso)) / DAY_MS);
  return days === 0 ? 0 : days; // never -0
}

// ─── Colours ─────────────────────────────────────────────────────────────────

export const TONE = { good: '#10b981', warn: '#f59e0b', bad: '#ef4444', unknown: '#94a3b8' } as const;

export function rgb(hex: string): string {
  const h = hex.replace('#', '');
  const channel = (i: number) => parseInt(h.slice(i, i + 2), 16);
  return `rgb(${channel(0)}, ${channel(2)}, ${channel(4)})`;
}

export function expiryTone(days: number | null): keyof typeof TONE {
  if (days === null) return 'unknown';
  if (days < 0) return 'bad';
  return days > 30 ? 'good' : 'warn';
}

export function dnssecTone(state: string): keyof typeof TONE {
  return state === 'signed' ? 'good' : state === 'unsigned' ? 'warn' : 'unknown';
}

// ─── Snapshot completion ─────────────────────────────────────────────────────

const text = (v: unknown) => (typeof v === 'string' ? v : '');
const list = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []);
const person = (v: unknown): Contact => {
  const c = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
  return { name: text(c.name), email: text(c.email), phone: text(c.phone) };
};

/**
 * The snapshot the page works with for a given API answer: the answer itself
 * when it is complete, neutral defaults for whatever is missing or mistyped.
 * `nowIso` is the browser clock, used only when the answer has no check time.
 */
export function completeSnapshot(answer: unknown, nowIso: string): Snapshot {
  const a = (answer && typeof answer === 'object' ? answer : {}) as Record<string, unknown>;
  const contacts = (a.contacts && typeof a.contacts === 'object' ? a.contacts : {}) as Record<string, unknown>;
  const meta = a.rdap_metadata && typeof a.rdap_metadata === 'object' ? a.rdap_metadata as Record<string, unknown> : null;
  const rawWhois = text(a.raw_whois);
  return {
    domain: text(a.domain),
    query_domain: typeof a.query_domain === 'string' ? a.query_domain : text(a.domain),
    data_source: a.data_source === 'rdap' ? 'rdap' : 'whois',
    registered: Boolean(a.registered),
    status_labels: list(a.status_labels),
    status_codes: list(a.status_codes),
    registrar: text(a.registrar),
    registrar_iana_id: text(a.registrar_iana_id),
    abuse_email: text(a.abuse_email),
    abuse_phone: text(a.abuse_phone),
    creation_date: text(a.creation_date),
    updated_date: text(a.updated_date),
    expiry_date: text(a.expiry_date),
    days_until_expiry: typeof a.days_until_expiry === 'number' ? a.days_until_expiry : null,
    nameservers: list(a.nameservers),
    dns_nameservers: list(a.dns_nameservers),
    nameserver_match: typeof a.nameserver_match === 'boolean' ? a.nameserver_match : null,
    nameserver_only_in_whois: list(a.nameserver_only_in_whois),
    nameserver_only_in_dns: list(a.nameserver_only_in_dns),
    dnssec: a.dnssec === 'signed' || a.dnssec === 'unsigned' ? a.dnssec : 'unknown',
    privacy_detected: Boolean(a.privacy_detected),
    privacy_provider: text(a.privacy_provider),
    contacts: { registrant: person(contacts.registrant), admin: person(contacts.admin), tech: person(contacts.tech) },
    risk_signals: list(a.risk_signals),
    raw_response: typeof a.raw_response === 'string' ? a.raw_response : rawWhois,
    raw_whois: rawWhois,
    rdap_metadata: meta ? { base_url: text(meta.base_url), handle: text(meta.handle) } : null,
    checked_at_utc: typeof a.checked_at_utc === 'string' ? a.checked_at_utc : nowIso,
  };
}

// ─── What the page must show ─────────────────────────────────────────────────

export interface ContactCard { label: string; lines: string[] }

export interface WhoisView {
  /** Summary cards in order: [label, value]. */
  cards: [string, string][];
  daysColor: string;
  dnssecColor: string;
  source: string;
  checkedAt: string;
  /** Section headings in order. */
  sections: string[];
  statusPills: string[];
  statusNote: string | null;
  registrar: [string, string][];
  nameservers: [string, string][];
  links: [string, string][];
  contacts: ContactCard[];
  riskItems: string[];
  riskNote: string | null;
  rawToggle: string;
}

export const sourceWord = (s: Snapshot) => (s.data_source === 'rdap' ? 'RDAP' : 'WHOIS');
const orNone = (items: string[]) => (items.length ? items.join(', ') : 'None');
const orUnknown = (value: string) => (value === '' ? 'Unknown' : value);

export function contactCards(s: Snapshot): ContactCard[] {
  const roles: [string, Contact][] = [['Registrant', s.contacts.registrant], ['Admin', s.contacts.admin], ['Tech', s.contacts.tech]];
  return roles
    .map(([label, c]) => ({ label, lines: [c.name, c.email, c.phone].filter(part => part !== '') }))
    .filter(card => card.lines.length > 0);
}

export function rawText(s: Snapshot): string {
  if (s.raw_response !== '') return s.raw_response;
  if (s.raw_whois !== '') return s.raw_whois;
  return `No raw ${sourceWord(s)} data available.`;
}

export function expectedView(s: Snapshot): WhoisView {
  const src = sourceWord(s);
  const cards = contactCards(s);
  const privacy = !s.privacy_detected ? 'Not detected' : s.privacy_provider === '' ? 'Detected' : s.privacy_provider;
  const match = s.nameserver_match === null ? 'Unknown' : s.nameserver_match ? 'Yes' : 'No';
  return {
    cards: [
      ['Domain', s.domain],
      ['Registration', s.registered ? 'Registered' : 'Unknown / Not Found'],
      ['Registrar', orUnknown(s.registrar)],
      ['Days Until Expiry', s.days_until_expiry === null ? 'Unknown' : String(s.days_until_expiry)],
      ['DNSSEC', s.dnssec],
    ],
    daysColor: rgb(TONE[expiryTone(s.days_until_expiry)]),
    dnssecColor: rgb(TONE[dnssecTone(s.dnssec)]),
    source: src,
    checkedAt: utcStamp(s.checked_at_utc),
    sections: ['Domain Status', 'Registrar & Dates', 'Nameserver Comparison', ...(cards.length ? ['Contacts'] : []), 'Risk Signals', `Raw ${src}`],
    statusPills: s.status_labels,
    statusNote: s.status_labels.length ? null : `No explicit status values parsed from ${src}.`,
    registrar: [
      ['Source', src],
      ['Registrar', orUnknown(s.registrar)],
      ['Registrar IANA ID', orUnknown(s.registrar_iana_id)],
      ['Abuse Email', orUnknown(s.abuse_email)],
      ['Abuse Phone', orUnknown(s.abuse_phone)],
      ['Creation Date', utcStamp(s.creation_date)],
      ['Updated Date', utcStamp(s.updated_date)],
      ['Expiry Date', utcStamp(s.expiry_date)],
      ['Privacy', privacy],
    ],
    nameservers: [
      [`${src} Nameservers`, orNone(s.nameservers)],
      ['Live DNS Nameservers', orNone(s.dns_nameservers)],
      ['Exact Match', match],
      [`Only In ${src}`, orNone(s.nameserver_only_in_whois)],
      ['Only In DNS', orNone(s.nameserver_only_in_dns)],
    ],
    links: [
      ['Open DNS Lookup', `/dns?domain=${encodeURIComponent(s.domain)}&types=NS`],
      ['Open SSL Checker', `/ssl?domain=${encodeURIComponent(s.domain)}`],
    ],
    contacts: cards,
    riskItems: s.risk_signals,
    riskNote: s.risk_signals.length ? null : 'No risk signals were generated for this snapshot.',
    rawToggle: `Show Raw ${src}`,
  };
}

// ─── What leaves the page ────────────────────────────────────────────────────

/** Text the "Copy Summary" button puts on the clipboard: one `Label: value` per line. */
export function expectedSummary(s: Snapshot): string {
  const src = sourceWord(s);
  const rows: [string, string][] = [
    ['Domain', s.domain],
    ['Data Source', src],
    ['Registered', s.registered ? 'Yes' : 'No / Unknown'],
    ['Registrar', orUnknown(s.registrar)],
    ['Registrar IANA ID', orUnknown(s.registrar_iana_id)],
    ['Creation Date', utcStamp(s.creation_date)],
    ['Updated Date', utcStamp(s.updated_date)],
    ['Expiry Date', utcStamp(s.expiry_date)],
    ['Days Until Expiry', s.days_until_expiry === null ? 'Unknown' : String(s.days_until_expiry)],
    ['DNSSEC', s.dnssec],
    ['Privacy Detected', !s.privacy_detected ? 'No' : s.privacy_provider === '' ? 'Yes' : s.privacy_provider],
    ['Statuses', orNone(s.status_labels)],
    [`${src} Nameservers`, orNone(s.nameservers)],
    ['Live DNS Nameservers', orNone(s.dns_nameservers)],
    ['Risk Signals', s.risk_signals.length ? s.risk_signals.join(' | ') : 'None'],
  ];
  return rows.map(([label, value]) => `${label}: ${value}`).join('\n');
}

/** Content of the downloadable HTML report, as plain data. */
export interface ReportView {
  title: string;
  heading: string;
  subtitle: string;
  cards: [string, string][];
  statusPills: string[];
  statusNote: string | null;
  details: [string, string][];
  nameservers: [string, string][];
  riskItems: string[];
  riskNote: string | null;
  rawHeading: string;
  raw: string;
}

export function expectedReport(s: Snapshot): ReportView {
  const src = sourceWord(s);
  const view = expectedView(s);
  const pick = (rows: [string, string][], label: string) => rows.find(([name]) => name === label)![1];
  return {
    title: `${src} Snapshot - ${s.domain}`,
    heading: `${src} Snapshot`,
    subtitle: `${s.domain} - Checked ${utcStamp(s.checked_at_utc)}`,
    cards: view.cards,
    statusPills: s.status_labels,
    statusNote: s.status_labels.length ? null : 'No explicit statuses parsed',
    details: [
      ['Creation Date', utcStamp(s.creation_date)],
      ['Updated Date', utcStamp(s.updated_date)],
      ['Expiry Date', utcStamp(s.expiry_date)],
      ['Registrar IANA ID', orUnknown(s.registrar_iana_id)],
      ['Abuse Email', orUnknown(s.abuse_email)],
      ['Abuse Phone', orUnknown(s.abuse_phone)],
      ['Privacy', pick(view.registrar, 'Privacy')],
      ['Source', src],
    ],
    nameservers: [
      [`${src} Nameservers`, orNone(s.nameservers)],
      ['Live DNS Nameservers', orNone(s.dns_nameservers)],
      ['Nameserver Match', pick(view.nameservers, 'Exact Match')],
    ],
    riskItems: s.risk_signals,
    riskNote: s.risk_signals.length ? null : 'No additional risk signals.',
    rawHeading: `Raw ${src}`,
    raw: rawText(s),
  };
}

/**
 * One-row CSV export: a column per leaf field. Nested objects become columns
 * named with the path joined by spaces (`contacts registrant name`); a list is
 * written as JSON text; null, booleans and numbers as their JSON literal.
 */
export function csvRecord(value: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  const walk = (node: unknown, path: string[]) => {
    if (node !== null && typeof node === 'object' && !Array.isArray(node)) {
      for (const [key, child] of Object.entries(node as Record<string, unknown>)) walk(child, [...path, key]);
      return;
    }
    out[path.join(' ')] = Array.isArray(node) ? JSON.stringify(node) : String(node);
  };
  walk(value, []);
  return out;
}

// ─── Backend rules, restated for live checks and for the generator ───────────

/**
 * Readable label for a registry status code (EPP RFC 5731 / RDAP RFC 8056).
 * Returns null for codes this table does not cover.
 */
export function statusLabel(code: string): string | null {
  const key = code.toLowerCase().replace(/[^a-z]/g, '');
  const table: Record<string, string> = {
    clienttransferprohibited: 'Transfer Locked',
    servertransferprohibited: 'Registry Transfer Locked',
    clientdeleteprohibited: 'Delete Locked',
    serverdeleteprohibited: 'Registry Delete Locked',
    clientupdateprohibited: 'Update Locked',
    serverupdateprohibited: 'Registry Update Locked',
    pendingdelete: 'Pending Delete',
    pendingtransfer: 'Pending Transfer',
    clienthold: 'On Hold',
    serverhold: 'On Hold',
    ok: 'Active',
    active: 'Active',
  };
  return table[key] ?? null;
}

/** Which nameservers are on one side only, each list sorted; and whether the sets are equal. */
export function compareNameservers(registry: string[], dns: string[]) {
  const left = new Set(registry.map(n => n.toLowerCase()));
  const right = new Set(dns.map(n => n.toLowerCase()));
  const onlyRegistry = [...left].filter(n => !right.has(n)).sort();
  const onlyDns = [...right].filter(n => !left.has(n)).sort();
  return { match: onlyRegistry.length === 0 && onlyDns.length === 0, onlyRegistry, onlyDns };
}

/**
 * Risk sentences the backend attaches to a snapshot, from the snapshot's own
 * fields. `nowIso` is the check time.
 */
export function riskSignals(s: Omit<Snapshot, 'risk_signals'>, nowIso: string): string[] {
  const out: string[] = [];
  const days = s.days_until_expiry;
  if (days !== null) {
    if (days < 0) out.push('Domain appears expired.');
    else if (days <= 14) out.push('Domain expires within 14 days.');
    else if (days <= 30) out.push('Domain expires within 30 days.');
  }
  if (s.creation_date) {
    const ageDays = Math.floor((Date.parse(nowIso) - Date.parse(s.creation_date)) / DAY_MS);
    if (ageDays >= 0 && ageDays <= 30) out.push('Domain was registered within the last 30 days.');
  }
  if (s.privacy_detected) out.push('Registration data privacy or redaction is enabled.');
  if (s.nameserver_match === false) out.push(`${sourceWord(s as Snapshot)} nameservers differ from live DNS NS records.`);
  if (s.dnssec === 'unsigned') out.push('No live DNSSEC DS record detected.');
  if (s.dnssec === 'unknown') out.push('Could not determine live DNSSEC state.');
  const compact = s.status_codes.map(code => code.toLowerCase().replace(/\s+/g, ''));
  if (compact.some(code => code.includes('hold'))) out.push('Domain status indicates hold or suspension.');
  if (compact.some(code => code.includes('pendingdelete'))) out.push('Domain is pending delete.');
  if (compact.some(code => code.includes('transferprohibited'))) out.push('Domain transfer is restricted.');
  if (!s.registered && out.length === 0) out.push('Domain appears unregistered or registration data did not return an active record.');
  return out;
}

/** Inputs the real backend must refuse: none of them is a registrable domain name. */
export const NOT_DOMAINS: { input: string; why: string }[] = [
  { input: 'localhost', why: 'single label, no TLD' },
  { input: 'exa mple.com', why: 'space inside the name' },
  { input: '-bad.com', why: 'label starts with a hyphen' },
  { input: 'bad-.com', why: 'label ends with a hyphen' },
  { input: 'a..com', why: 'empty label' },
  { input: 'under_score.com', why: 'underscore is not allowed in a host name' },
  { input: 'exam!ple.com', why: 'punctuation in the name' },
  { input: `${'a'.repeat(64)}.com`, why: 'label longer than 63 characters' },
  { input: '<img src=x onerror=alert(1)>', why: 'markup' },
];
